return {["fb212_01"]={["down"]=[[fb212_25]],["dsc"]=[[此处是连接两层楼的楼道。楼道全由实木建成，设有栏杆，漆有红漆。栏杆上雕花细致，似是大家手笔。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_01]],["item1"]=[[tldj2]],["item2"]=[[tllt1]],["left"]=[[fb212_20]],["name"]=[[楼道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb212_16]]},["fb212_02"]={["down"]=[[fb212_09]],["dsc"]=[[此处是走廊转角处的回廊。回廊是木质，其上铺有毛毯，踩上去柔软舒适。回廊的廊柱均是以浮雕装饰，颇为不凡。廊柱之下摆放有凳子，可供人休息。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_02]],["name"]=[[回廊]],["permission"]=1,["right"]=[[fb212_03]],["stepMusic"]=[[jiaobu]]},["fb212_03"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_03]],["item1"]=[[212dj13]],["left"]=[[fb212_02]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb212_04]],["stepMusic"]=[[jiaobu]]},["fb212_04"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_04]],["left"]=[[fb212_03]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb212_05]],["stepMusic"]=[[jiaobu]]},["fb212_05"]={["down"]=[[fb212_10]],["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_05]],["left"]=[[fb212_04]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb212_06]],["stepMusic"]=[[jiaobu]]},["fb212_06"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_06]],["left"]=[[fb212_05]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb212_07]],["stepMusic"]=[[jiaobu]]},["fb212_07"]={["dsc"]=[[此处是连接各处房间的走廊。走廊是木质，其上铺有毛毯，踩上去柔软舒适。走廊十分宽阔，每隔几尺便装有壁灯，壁灯在晚上便会全部点亮，楼内便会灯火通明。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb212_07]],["item1"]=[[212dj14]],["left"]=[[fb212_06]],["name"]=[[走廊]],["permission"]=1,["right"]=[[fb212_08]],["stepMusic"]=[[jiaobu]]},["fb212_08"]={["down"]=[[fb212_11]],["dsc"]=[[此处是走廊转角处的回廊。回廊是木质，其上铺有毛毯，踩上去柔软舒适。回廊的廊柱均是以浮雕装饰，颇为不凡。廊柱之下摆放有凳子，可供人休息。]],["fightBackground"